<?php require_once __DIR__.'/includes/auth.php'; require_login(); $user=current_user(); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $all=users(); $email=$_SESSION['user_email']; $all[$email]['farm_size']=(float)$_POST['farm_size']; $all[$email]['crop_type']=trim($_POST['crop_type']); $all[$email]['soil_quality']=soil_value($_POST['soil_quality']); write_json(USERS_FILE,$all); $message='Profile updated.'; $user=$all[$email]; } ?><!doctype html><html lang="en"><head><?php include __DIR__.'/includes/head.php'; ?><title>Profile | Kudla kwesive</title></head><body><header class="topbar"><a class="brand" href="dashboard.php">KUDLA <span>KWESIVE</span></a><a class="text-link" href="logout.php">Log out</a></header><main class="narrow"><p class="kicker">Your farm profile</p><h1><?=e($user['name'])?></h1><?php if($message): ?><div class="alert success"><?=e($message)?></div><?php endif; ?><form method="post" class="profile-form"><label>Region<input value="<?=e($user['region'])?>" disabled></label><label>Farm size (ha)<input type="number" name="farm_size" min=".5" max="100" step=".1" value="<?=e($user['farm_size'])?>"></label><label>Primary crop<input name="crop_type" value="<?=e($user['crop_type'])?>"></label><label>Soil quality<select name="soil_quality"><?php foreach(['Poor','Moderate','Good','Excellent'] as $s): ?><option <?=soil_label($user['soil_quality'])===$s?'selected':''?>><?=e($s)?></option><?php endforeach; ?></select></label><button class="button" type="submit">Save profile <span>→</span></button></form></main></body></html>